14	/// Complete the given command, shell-agnostic
15	pub fn complete(
16	    cmd: &mut clap::Command,
17	    args: Vec<OsString>,
18	    arg_index: usize,
19	    current_dir: Option<&std::path::Path>,
20	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
21	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
22	    cmd.build();
23	
24	    let mut final_len = args.len();
25	    let mut raw_args = clap_lex::RawArgs::new(args);
26	
27	    // A multicall binary chooses its applet from the file name it was invoked
28	    // as, just like the parser reinterprets `argv[0]` as the first word. The
29	    // resolved applet is inserted right after `argv[0]` so the regular loop
30	    // descends into it; from then on completion is scoped to that applet and
31	    // never sees the aggregate command's root.
32	    //
33	    // `arg_index` addresses the words the caller passed, where `argv[0]` is
34	    // index 0. The inserted word sits at index 1, so a cursor on any later word
35	    // moves one position to the right.
36	    let mut arg_index = arg_index;
37	    // Whether the resolved applet was inserted right after `argv[0]`.
38	    let mut descended_applet = false;
39	    if cmd.is_multicall_set() {
40	        let mut argv0_cursor = raw_args.cursor();
41	        if let Some(argv0) = raw_args.next_os(&mut argv0_cursor) {
42	            if let Some(applet) = std::path::Path::new(argv0)
43	                .file_stem()
44	                .and_then(|file_stem| file_stem.to_str())
45	            {
46	                // Borrow `cmd` through an owned name so `raw_args` can be mutated.
47	                let applet = applet.to_owned();
48	                if cmd.find_subcommand(&applet).is_none() {
49	                    return Err(std::io::Error::other(format!(
50	                        "unrecognized multicall command `{applet}`"
51	                    )));
52	                }
53	                raw_args.insert(&argv0_cursor, [OsString::from(applet)]);
54	                descended_applet = true;
55	                final_len += 1;
56	                if arg_index != 0 {
57	                    arg_index += 1;
58	                }
59	            }
60	        }
61	    }
62	
63	    // A cursor at or past the final word names nothing to complete. (Shells
64	    // that complete a freshly typed empty word append it to `args` and address
65	    // its index instead, so it is still completed normally.)
66	    if arg_index >= final_len {
67	        return Ok(Vec::new());
68	    }
69	    // In multicall mode `argv[0]` was consumed to select the applet and is no
70	    // longer a logical word, so a cursor on it completes nothing rather than
71	    // erroring or completing at the aggregate root. This keeps no-binary-name
72	    // cursor semantics: logical words begin after the resolved applet.
73	    if descended_applet && arg_index == 0 {
74	        return Ok(Vec::new());
75	    }
76	
77	    let mut cursor = raw_args.cursor();
78	    let mut target_cursor = raw_args.cursor();
79	    raw_args.seek(
80	        &mut target_cursor,
81	        clap_lex::SeekFrom::Start(arg_index as u64),
82	    );
83	    // As we loop, `cursor` will always be pointing to the next item
84	    raw_args.next_os(&mut target_cursor);
85	    debug!("complete: target_cursor={target_cursor:?}");
86	
87	    // Multicall already consumed `argv[0]` to select the applet and inserted
88	    // that applet in its place, so it is never parsed as a word again, even in
89	    // no-binary-name mode. Without multicall, `argv[0]` is skipped as the
90	    // binary name unless `no_binary_name` is set.
91	    if descended_applet || !cmd.is_no_binary_name_set() {
92	        raw_args.next_os(&mut cursor);
93	    }
94	
95	    let mut current_cmd = &*cmd;
96	    let mut pos_index = 1;
97	    let mut is_escaped = false;
98	    let mut next_state = ParseState::ValueDone;
99	    let mut used_args = Vec::<clap::Id>::new();
100	    // Once a committed word selected an external subcommand, every remaining
101	    // word belongs to that external program and is never completed here.
102	    let mut in_external = false;
103	    while let Some(arg) = raw_args.next(&mut cursor) {
104	        let current_state = next_state;
105	        next_state = ParseState::ValueDone;
106	        debug!(
107	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
108	            arg.to_value_os(),
109	        );
110	        if let ParseState::Opt(state) = &current_state {
111	            // A value terminator ends a multi-value option regardless of the
112	            // word's shape: unlike a flag-like word, it never starts a new
113	            // argument, and unlike any other word, it is never one of the
114	            // option's values. A flag-shaped terminator only wins over flag
115	            // parsing when the option accepts hyphen values, matching the
116	            // parser's precedence.
117	            let opt = state.opt;
118	            if is_value_terminator(opt, &arg)
119	                && (opt.is_allow_hyphen_values_set() || !is_flag_like(&arg))
120	            {
121	                if cursor == target_cursor {
122	                    // The cursor sits on the terminator itself. Complete as if
123	                    // it had already been submitted and an empty word followed,
124	                    // so ordinary completion resumes and the terminator is not
125	                    // offered as a candidate.
126	                    raw_args.insert(&target_cursor, [OsString::new()]);
127	                    let mut word_cursor = target_cursor;
128	                    let word = raw_args
129	                        .next(&mut word_cursor)
130	                        .expect("an empty word was just inserted");
131	                    return complete_arg(
132	                        &word,
133	                        current_cmd,
134	                        current_dir,
135	                        pos_index,
136	                        is_escaped,
137	                        ParseState::ValueDone,
138	                        &used_args,
139	                    );
140	                }
141	                next_state = ParseState::ValueDone;
142	                continue;
143	            }
144	        }
145	        if in_external {
146	            // A committed word already selected an external subcommand; this
147	            // word (and every later one) is an argument of that external
148	            // program. Its command line is unknown, so rather than falling
149	            // back to the current command's subcommands, options, or
150	            // positionals, completion succeeds with an empty set.
151	            if cursor == target_cursor {
152	                return Ok(Vec::new());
153	            }
154	            continue;
155	        }
156	
157	        if cursor == target_cursor {
158	            return complete_arg(
159	                &arg,
160	                current_cmd,
161	                current_dir,
162	                pos_index,
163	                is_escaped,
164	                current_state,
165	                &used_args,
166	            );
167	        }
168	
169	        if !is_escaped && !matches!(current_state, ParseState::Opt(..) | ParseState::Pos(..)) {
170	            if let Ok(value) = arg.to_value() {
171	                if let Some(next_cmd) = current_cmd.find_subcommand(value) {
172	                    current_cmd = next_cmd;
173	                    pos_index = 1;
174	                    used_args.clear();
175	                    continue;
176	                }
177	                // An unknown plain word, with no positional slot left to
178	                // fill, selects an external subcommand: the parser routes
179	                // everything after it to that external program. Flag-like
180	                // words and the escape are still parsed as flags, matching
181	                // that precedence, and an empty word is a cursor placeholder
182	                // rather than a program name.
183	                if current_cmd.is_allow_external_subcommands_set()
184	                    && !arg.is_empty()
185	                    && !arg.is_escape()
186	                    && arg.to_long().is_none()
187	                    && arg.to_short().is_none()
188	                    && find_positional(current_cmd, pos_index, false).is_none()
189	                {
190	                    in_external = true;
191	                    continue;
192	                }
193	            }
194	        }
195	
196	        // A strict delimited group whose previous word opened another fragment
197	        // (a trailing delimiter) or went invalid owns the next word outright: a
198	        // flag, the `--` escape, or a subcommand name is then another value of
199	        // the group, never a scope switch. A continuation word that fills the
200	        // group closes it; otherwise the group stays pending for its remaining
201	        // fragments.
202	        if let ParseState::Opt(state) = &current_state {
203	            if state.is_strict_group() && (state.open || state.invalid) {
204	                let mut state = state.clone();
205	                state.observe(arg.to_value_os(), false);
206	                next_state =
207	                    if !state.invalid && !state.open && state.used.len() == state.capacity() {
208	                        ParseState::ValueDone
209	                    } else {
210	                        ParseState::Opt(state)
211	                    };
212	                continue;
213	            }
214	        }
215	
216	        if is_escaped {
217	            (next_state, pos_index) =
218	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
219	        } else if arg.is_escape() {
220	            is_escaped = true;
221	            // Like the parser, `--` jumps straight to a `last(true)`
222	            // positional, skipping any unfilled positionals.
223	            if let Some(last_index) = current_cmd
224	                .get_positionals()
225	                .filter(|p| p.is_last_set())
226	                .filter_map(|p| p.get_index())
227	                .max()
228	            {
229	                pos_index = last_index;
230	            }
231	        } else if opt_allows_hyphen(&current_state, &arg) {
232	            match current_state {
233	                ParseState::Opt(mut state) => {
234	                    state.observe(arg.to_value_os(), false);
235	                    next_state = state.finish();
236	                }
237	                _ => unreachable!("else branch is only reachable in Opt state"),
238	            }
239	        } else if let Some((flag, value)) = arg.to_long() {
240	            if let Ok(flag) = flag {
241	                let opt = current_cmd.get_arguments().find(|a| is_long_match(a, flag));
242	
243	                if let Some(opt) = opt {
244	                    record_used_arg(&mut used_args, opt.get_id());
245	                    if opt.get_num_args().expect("built").takes_values() {
246	                        // An attached value (`--opt=value`) counts toward the
247	                        // option's values just like a space-separated one, so
248	                        // that completing after `--opt=value` sees the same
249	                        // state as completing after `--opt value`.
250	                        // An empty attached value (`--opt=`) types no value
251	                        // yet, so the option stays pending.
252	                        let mut state = OptState::new(opt);
253	                        if let Some(value) = value.filter(|v| !v.is_empty()) {
254	                            state.observe(value, true);
255	                        }
256	                        next_state = state.finish();
257	                    };
258	                } else if pos_allows_hyphen(current_cmd, pos_index) {
259	                    (next_state, pos_index) =
260	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
261	                }
262	            }
263	        } else if let Some(short) = arg.to_short() {
264	            let (_, matched_opts, takes_value_opt, mut short) =
265	                parse_shortflags(current_cmd, short);
266	            for opt in &matched_opts {
267	                record_used_arg(&mut used_args, opt.get_id());
268	            }
269	            if let Some(opt) = takes_value_opt {
270	                // An attached value (`-ovalue`, `-o=value`) counts toward the
271	                // option's values just like a space-separated one. An empty
272	                // attached value (`-o=`) types no value yet, so the option
273	                // stays pending instead of being treated as satisfied.
274	                let mut state = OptState::new(opt);
275	                if let Some(value) = short
276	                    .next_value_os()
277	                    .map(|v| v.strip_prefix("=").unwrap_or(v))
278	                    .filter(|v| !v.is_empty())
279	                {
280	                    state.observe(value, true);
281	                }
282	                next_state = state.finish();
283	            } else if pos_allows_hyphen(current_cmd, pos_index) {
284	                (next_state, pos_index) =
285	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
286	            }
287	        } else {
288	            match current_state {
289	                ParseState::ValueDone | ParseState::Pos(..) => {
290	                    (next_state, pos_index) =
291	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
292	                }
293	                ParseState::Opt(mut state) => {
294	                    state.observe(arg.to_value_os(), false);
295	                    next_state = state.finish();
296	                }
297	            }
298	        }
299	    }
300	
301	    Err(std::io::Error::other("no completion generated"))
302	}
