304	#[derive(Debug, PartialEq, Eq, Clone)]
305	enum ParseState<'a> {
306	    /// Parsing a value done, there is no state to record.
307	    ValueDone,
308	
309	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
310	    Pos((usize, usize)),
311	
312	    /// Parsing a optional flag argument
313	    Opt(OptState<'a>),
314	}
315	
316	/// State kept while the values of an option are still being parsed.
317	#[derive(Debug, PartialEq, Eq, Clone)]
318	struct OptState<'a> {
319	    opt: &'a clap::Arg,
320	    /// Shell-word values consumed, counted the way the parser does so that
321	    /// [`ArgValueCompleter::complete_at`] keeps indexing shell arguments
322	    /// rather than delimiter-separated fragments.
323	    words: usize,
324	    /// Canonical possible-value names of the valid, committed fragments of
325	    /// the current occurrence. Only populated for strict delimited groups.
326	    used: Vec<String>,
327	    /// Whether the most recent shell word ended with the value delimiter, so
328	    /// the word under the cursor is still filling this group (and may not
329	    /// switch scope no matter how it is shaped).
330	    open: bool,
331	    /// Whether a committed fragment of the current group was invalid (empty,
332	    /// unknown, duplicated, or past the group's capacity). Such a group stays
333	    /// locked on value completion and never yields candidates or lets a later
334	    /// word switch scope.
335	    invalid: bool,
336	}
337	
338	impl<'a> OptState<'a> {
339	    fn new(opt: &'a clap::Arg) -> Self {
340	        Self {
341	            opt,
342	            words: 0,
343	            used: Vec::new(),
344	            open: false,
345	            invalid: false,
346	        }
347	    }
348	
349	    fn is_strict_group(&self) -> bool {
350	        is_strict_group_arg(self.opt)
351	    }
352	
353	    /// Maximum number of values the option accepts; for strict delimited
354	    /// groups this is the number of fragments allowed in one occurrence.
355	    fn capacity(&self) -> usize {
356	        self.opt.get_num_args().expect("built").max_values()
357	    }
358	
359	    /// Record a shell word as a value of this option.
360	    ///
361	    /// `attached` marks a value glued to its flag (`--opt=a,b`). For options
362	    /// whose delimiter is not a strict group, such a word counts every
363	    /// delimiter-separated fragment toward the value range; a space-separated
364	    /// word counts once. For strict groups the fragments are instead validated
365	    /// into `used`, except the empty slot still being typed after a trailing
366	    /// delimiter.
367	    fn observe(&mut self, word: &OsStr, attached: bool) {
368	        if !self.is_strict_group() {
369	            let count = if attached {
370	                attached_value_count(self.opt, word)
371	            } else {
372	                1
373	            };
374	            self.words += count;
375	            return;
376	        }
377	
378	        self.words += 1;
379	        if self.invalid {
380	            return;
381	        }
382	        let delimiter = self.opt.get_value_delimiter().expect("strict group");
383	        let capacity = self.capacity();
384	        self.open = word.to_string_lossy().ends_with(delimiter);
385	        let Some(word) = word.to_str() else {
386	            self.invalid = true;
387	            return;
388	        };
389	        let mut fragments = word.split(delimiter);
390	        if self.open {
391	            // A trailing delimiter opens the slot still being typed, so its
392	            // empty fragment is not a committed value.
393	            fragments.next_back();
394	        }
395	        for fragment in fragments {
396	            if self.used.len() >= capacity {
397	                self.invalid = true;
398	                break;
399	            }
400	            match canonical_possible_value(self.opt, fragment) {
401	                Some(name) if !self.used.contains(&name) => self.used.push(name),
402	                _ => {
403	                    // Empty (also a doubled delimiter), unknown, or duplicated
404	                    // fragment: the parser would reject this group.
405	                    self.invalid = true;
406	                    break;
407	                }
408	            }
409	        }
410	    }
411	
412	    /// Consume a value and return the state parsing should resume with.
413	    ///
414	    /// The delimiter separates several fragments within one shell word, so a
415	    /// word that does not end with the delimiter is a complete value group and
416	    /// ordinary parsing resumes on the next word. A trailing delimiter instead
417	    /// opens a fragment still being typed, and an invalid committed fragment
418	    /// cannot be salvaged; both keep the group locked on values. An empty
419	    /// attached value (`--opt=`) leaves the option waiting for its first value.
420	    fn finish(self) -> ParseState<'a> {
421	        if self.is_strict_group() {
422	            if self.words == 0 || self.invalid || self.open {
423	                ParseState::Opt(self)
424	            } else {
425	                ParseState::ValueDone
426	            }
427	        } else if self.words >= self.capacity() {
428	            ParseState::ValueDone
429	        } else {
430	            ParseState::Opt(self)
431	        }
432	    }
433	}
434	
435	/// Whether an option's values form a delimited group that can hold more than
436	/// one fragment and whose fragments are validated while typed.
437	///
438	/// Single-value options (a maximum of one) are excluded: their delimiter only
439	/// joins several suggestions into one word, so completed fragments are not
440	/// validated against each other.
441	fn is_strict_group_arg(arg: &clap::Arg) -> bool {
442	    arg.get_value_delimiter().is_some()
443	        && arg.get_num_args().expect("built").max_values() > 1
444	        && possible_values(arg).is_some()
445	}
446	
447	/// The canonical possible-value name for `fragment`, honoring aliases and the
448	/// argument's case-insensitivity, or `None` when it is not a legal value.
449	fn canonical_possible_value(arg: &clap::Arg, fragment: &str) -> Option<String> {
450	    let ignore_case = arg.is_ignore_case_set();
451	    possible_values(arg)?
452	        .find(|value| value.matches(fragment, ignore_case))
453	        .map(|value| value.get_name().to_owned())
454	}
455	
456	/// Complete the word under the cursor for a strict delimited group.
457	///
458	/// Fragments already committed in earlier shell words are read from `state`;
459	/// fragments committed within the word under the cursor are validated here.
460	/// The fragment still being typed is matched against the possible values, and
461	/// every suggestion keeps the typed prefix (prior fragments and delimiters).
462	/// Any empty, unknown, duplicated, or over-capacity fragment yields an empty
463	/// result.
464	fn complete_strict_group(cursor: &str, state: &OptState<'_>) -> Vec<CompletionCandidate> {
465	    debug!(
466	        "complete_strict_group: arg={:?}, cursor={cursor:?}, used={:?}, invalid={}",
467	        state.opt.get_id(),
468	        state.used,
469	        state.invalid
470	    );
471	    if state.invalid {
472	        return Vec::new();
473	    }
474	    let delimiter = state.opt.get_value_delimiter().expect("strict group");
475	    let capacity = state.capacity();
476	
477	    let ends_with_delimiter = cursor.ends_with(delimiter);
478	    let mut parts = cursor.split(delimiter);
479	    let typed = if ends_with_delimiter {
480	        // The cursor sits right after a delimiter: the trailing empty element
481	        // is the fresh fragment being typed, not a committed value.
482	        parts.next_back();
483	        ""
484	    } else {
485	        parts.next_back().unwrap_or("")
486	    };
487	
488	    let mut used = state.used.clone();
489	    for fragment in parts {
490	        if used.len() >= capacity {
491	            return Vec::new();
492	        }
493	        match canonical_possible_value(state.opt, fragment) {
494	            Some(name) if !used.contains(&name) => used.push(name),
495	            _ => return Vec::new(),
496	        }
497	    }
498	
499	    if used.len() >= capacity {
500	        // Every slot is taken; there is no room for another fragment.
501	        return Vec::new();
502	    }
503	
504	    // Retain the text typed before the current fragment, including the last
505	    // delimiter, so suggestions replace only the fragment under the cursor.
506	    let prefix = cursor
507	        .rfind(delimiter)
508	        .map(|pos| cursor[..pos + delimiter.len_utf8()].to_owned());
509	
510	    let possible = possible_values(state.opt).expect("strict group");
511	    let mut values = complete_candidates_str(typed, possible_value_candidates(possible));
512	    // A value already committed to the group cannot be repeated.
513	    values.retain(|candidate| {
514	        candidate
515	            .get_value()
516	            .to_str()
517	            .is_none_or(|name| !used.iter().any(|used| used == name))
518	    });
519	
520	    if let Some(prefix) = prefix {
521	        values = values
522	            .into_iter()
523	            .map(|comp| comp.add_prefix(prefix.clone()))
524	            .collect();
525	    }
526	    values = values
527	        .into_iter()
528	        .map(|comp| {
529	            if comp.get_tag().is_some() {
530	                comp
531	            } else {
532	                comp.tag(Some(state.opt.to_string().into()))
533	            }
534	        })
535	        .collect();
536	
537	    values
538	}
539	
540	fn complete_arg(
541	    arg: &clap_lex::ParsedArg<'_>,
542	    cmd: &clap::Command,
543	    current_dir: Option<&std::path::Path>,
544	    pos_index: usize,
545	    is_escaped: bool,
546	    state: ParseState<'_>,
547	    used_args: &[clap::Id],
548	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
549	    debug!(
550	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
551	        arg,
552	        cmd.get_name(),
553	        current_dir,
554	        pos_index,
555	        state
556	    );
557	    let mut completions = Vec::<CompletionCandidate>::new();
558	
559	    match state {
560	        ParseState::ValueDone => {
561	            if !is_escaped {
562	                if let Ok(value) = arg.to_value() {
563	                    completions.extend(complete_subcommand(value, cmd));
564	                }
565	            }
566	
567	            if let Some(positional) = find_positional(cmd, pos_index, is_escaped) {
568	                completions.extend(complete_arg_value(
569	                    arg.to_value(),
570	                    positional,
571	                    current_dir,
572	                    0,
573	                ));
574	            }
575	            if !is_escaped {
576	                completions.extend(complete_option(arg, cmd, current_dir));
577	            }
578	        }
579	        ParseState::Pos((_, num_arg)) => {
580	            if let Some(positional) = find_positional(cmd, pos_index, is_escaped) {
581	                completions.extend(complete_arg_value(
582	                    arg.to_value(),
583	                    positional,
584	                    current_dir,
585	                    num_arg.saturating_sub(1),
586	                ));
587	                if !is_escaped
588	                    && positional
589	                        .get_num_args()
590	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
591	                {
592	                    completions.extend(complete_option(arg, cmd, current_dir));
593	                }
594	            }
595	        }
596	        ParseState::Opt(state) => {
597	            if state.is_strict_group() {
598	                // Every word belongs to the pending delimited group until it is
599	                // complete; it is never an option, positional, or subcommand.
600	                if let Ok(cursor) = arg.to_value() {
601	                    completions.extend(complete_strict_group(cursor, &state));
602	                }
603	            } else {
604	                let opt = state.opt;
605	                // `words` counts already-consumed values; the word under the
606	                // cursor is the next one, so the option sees one more value.
607	                let count = state.words + 1;
608	                completions.extend(complete_arg_value(
609	                    arg.to_value(),
610	                    opt,
611	                    current_dir,
612	                    count.saturating_sub(1),
613	                ));
614	                let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
615	                if count > min && can_switch_to_other_arg(opt, arg) {
616	                    // The option's required values are satisfied and this word
617	                    // would be parsed as a new flag rather than another value, so
618	                    // also complete it as a positional, flag, option or subcommand.
619	                    completions.extend(complete_arg(
620	                        arg,
621	                        cmd,
622	                        current_dir,
623	                        pos_index,
624	                        is_escaped,
625	                        ParseState::ValueDone,
626	                        used_args,
627	                    )?);
628	                }
629	            }
630	        }
631	    }
632	    filter_unavailable_args(&mut completions, cmd, used_args);
633	    if completions.iter().any(|a| !a.is_hide_set()) {
634	        completions.retain(|a| !a.is_hide_set());
635	    }
636	    dedup_argument_candidates(&mut completions, arg.is_empty());
637	
638	    let mut tags = Vec::new();
639	    for candidate in &completions {
640	        let tag = candidate.get_tag().cloned();
641	        if !tags.contains(&tag) {
642	            tags.push(tag);
643	        }
644	    }
645	    completions.sort_by_key(|c| {
646	        (
647	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
648	            c.get_display_order(),
649	        )
650	    });
651	
652	    Ok(completions)
653	}
