655	fn complete_option(
656	    arg: &clap_lex::ParsedArg<'_>,
657	    cmd: &clap::Command,
658	    current_dir: Option<&std::path::Path>,
659	) -> Vec<CompletionCandidate> {
660	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
661	    let mut completions = Vec::<CompletionCandidate>::new();
662	    if arg.is_empty() {
663	        completions.extend(longs_and_visible_aliases(cmd));
664	        completions.extend(hidden_longs_aliases(cmd));
665	
666	        let dash_or_arg = if arg.is_empty() {
667	            "-".into()
668	        } else {
669	            arg.to_value_os().to_string_lossy()
670	        };
671	        completions.extend(
672	            shorts_and_visible_aliases(cmd)
673	                .into_iter()
674	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
675	        );
676	    } else if arg.is_stdio() {
677	        // HACK: Assuming knowledge of is_stdio
678	        let dash_or_arg = if arg.is_empty() {
679	            "-".into()
680	        } else {
681	            arg.to_value_os().to_string_lossy()
682	        };
683	        completions.extend(
684	            shorts_and_visible_aliases(cmd)
685	                .into_iter()
686	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
687	        );
688	
689	        completions.extend(longs_and_visible_aliases(cmd));
690	        completions.extend(hidden_longs_aliases(cmd));
691	    } else if arg.is_escape() {
692	        // HACK: Assuming knowledge of is_escape
693	        completions.extend(longs_and_visible_aliases(cmd));
694	        completions.extend(hidden_longs_aliases(cmd));
695	    } else if let Some((flag, value)) = arg.to_long() {
696	        if let Ok(flag) = flag {
697	            if let Some(value) = value {
698	                if let Some(arg) = cmd.get_arguments().find(|a| is_long_match(a, flag)) {
699	                    if is_strict_group_arg(arg) {
700	                        // The whole attached word is the delimited group being
701	                        // typed, so its committed fragments are validated in
702	                        // place and only the fragment after the last delimiter
703	                        // is offered; the flag spelling is re-prefixed below.
704	                        if let Some(value) = value.to_str() {
705	                            let state = OptState::new(arg);
706	                            completions.extend(
707	                                complete_strict_group(value, &state)
708	                                    .into_iter()
709	                                    .map(|comp| comp.add_prefix(format!("--{flag}="))),
710	                            );
711	                        }
712	                    } else {
713	                        completions.extend(
714	                            complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
715	                                .into_iter()
716	                                .map(|comp| comp.add_prefix(format!("--{flag}="))),
717	                        );
718	                    }
719	                }
720	            } else {
721	                completions.extend(
722	                    longs_and_visible_aliases(cmd)
723	                        .into_iter()
724	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
725	                );
726	                completions.extend(
727	                    hidden_longs_aliases(cmd)
728	                        .into_iter()
729	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
730	                );
731	            }
732	        }
733	    } else if let Some(short) = arg.to_short() {
734	        if !short.is_negative_number() {
735	            // Find the first takes_values option.
736	            let (leading_flags, _, takes_value_opt, mut short) = parse_shortflags(cmd, short);
737	
738	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
739	            if let Some(opt) = takes_value_opt {
740	                let mut peek_short = short.clone();
741	                let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
742	                    short.next_flag();
743	                    true
744	                } else {
745	                    false
746	                };
747	
748	                let value = short.next_value_os().unwrap_or(OsStr::new(""));
749	                let group_completions = if is_strict_group_arg(opt) {
750	                    value
751	                        .to_str()
752	                        .map(|value| complete_strict_group(value, &OptState::new(opt)))
753	                        .unwrap_or_default()
754	                } else {
755	                    complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
756	                };
757	                completions.extend(group_completions.into_iter().map(|comp| {
758	                    let sep = if has_equal { "=" } else { "" };
759	                    comp.add_prefix(format!("-{leading_flags}{sep}"))
760	                }));
761	            } else {
762	                completions.extend(
763	                    shorts_and_visible_aliases(cmd)
764	                        .into_iter()
765	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
766	                );
767	            }
768	        }
769	    }
770	    debug!("complete_option: completions={completions:?}");
771	    completions
772	}
