774	fn complete_arg_value(
775	    value: Result<&str, &OsStr>,
776	    arg: &clap::Arg,
777	    current_dir: Option<&std::path::Path>,
778	    arg_index: usize,
779	) -> Vec<CompletionCandidate> {
780	    let mut values = Vec::new();
781	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
782	
783	    let (prefix, value) =
784	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
785	
786	    let value_os = match value {
787	        Ok(value) => OsStr::new(value),
788	        Err(value_os) => value_os,
789	    };
790	
791	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
792	        values.extend(completer.complete_at(arg_index, value_os));
793	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
794	        values.extend(complete_value_candidates(
795	            value_os,
796	            completer.value_candidates(),
797	        ));
798	    } else if let Some(possible_values) = possible_values(arg) {
799	        if let Ok(value) = value {
800	            values.extend(complete_candidates_str(
801	                value,
802	                possible_value_candidates(possible_values),
803	            ));
804	        }
805	    } else {
806	        match arg.get_value_hint() {
807	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
808	                // Should not complete
809	            }
810	            clap::ValueHint::AnyPath => {
811	                values.extend(complete_path(value_os, current_dir, &|_| true));
812	            }
813	            clap::ValueHint::FilePath => {
814	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
815	            }
816	            clap::ValueHint::DirPath => {
817	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
818	            }
819	            clap::ValueHint::ExecutablePath => {
820	                use is_executable::IsExecutable;
821	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
822	            }
823	            clap::ValueHint::CommandName
824	            | clap::ValueHint::CommandString
825	            | clap::ValueHint::CommandWithArguments
826	            | clap::ValueHint::Username
827	            | clap::ValueHint::Hostname
828	            | clap::ValueHint::Url
829	            | clap::ValueHint::EmailAddress => {
830	                // No completion implementation
831	            }
832	            _ => {
833	                // Safe-ish fallback
834	                values.extend(complete_path(value_os, current_dir, &|_| true));
835	            }
836	        }
837	
838	        values.sort();
839	    }
840	
841	    if let Some(prefix) = prefix {
842	        values = values
843	            .into_iter()
844	            .map(|comp| comp.add_prefix(prefix))
845	            .collect();
846	    }
847	    values = values
848	        .into_iter()
849	        .map(|comp| {
850	            if comp.get_tag().is_some() {
851	                comp
852	            } else {
853	                comp.tag(Some(arg.to_string().into()))
854	            }
855	        })
856	        .collect();
857	
858	    debug!("complete_arg_value: values={values:?}");
859	    values
860	}
