862	fn rsplit_delimiter<'s, 'o>(
863	    value: Result<&'s str, &'o OsStr>,
864	    delimiter: Option<char>,
865	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
866	    let delimiter = delimiter?;
867	    let value = value.ok()?;
868	    let pos = value.rfind(delimiter)?;
869	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
870	    Some((Some(prefix), Ok(value)))
871	}
