1007	/// Gets subcommands of [`clap::Command`] in the form of `("name", "bin_name")`.
1008	///
1009	/// Subcommand `rustup toolchain install` would be converted to
1010	/// `("install", "rustup toolchain install")`.
1011	fn subcommands(p: &clap::Command) -> Vec<CompletionCandidate> {
1012	    debug!("subcommands: name={}", p.get_name());
1013	    debug!("subcommands: Has subcommands...{:?}", p.has_subcommands());
1014	    p.get_subcommands()
1015	        .flat_map(|sc| {
1016	            sc.get_name_and_visible_aliases()
1017	                .into_iter()
1018	                .map(|s| populate_command_candidate(s, p, sc))
1019	                .chain(
1020	                    // A hidden alias keeps an undocumented spelling usable when
1021	                    // typed out exactly (descent goes through `find_subcommand`),
1022	                    // but it must never be offered as a suggestion of a visible
1023	                    // command. When the command itself is hidden, its aliases are
1024	                    // hidden too and are still emitted so that the all-hidden
1025	                    // fallback in `complete_arg` can keep the command reachable.
1026	                    sc.get_aliases()
1027	                        .filter(|_| sc.is_hide_set())
1028	                        .map(|s| populate_command_candidate(s, p, sc).hide(true)),
1029	                )
1030	        })
1031	        .collect()
1032	}
