1052	/// Parse the short flags and find the first `takes_values` option.
1053	///
1054	/// Returns the raw leading flags, every matched argument, the first
1055	/// `takes_values` option (if any), and the remaining unparsed flags.
1056	fn parse_shortflags<'c, 's>(
1057	    cmd: &'c clap::Command,
1058	    mut short: clap_lex::ShortFlags<'s>,
1059	) -> (
1060	    String,
1061	    Vec<&'c clap::Arg>,
1062	    Option<&'c clap::Arg>,
1063	    clap_lex::ShortFlags<'s>,
1064	) {
1065	    let takes_value_opt;
1066	    let mut matched_opts = Vec::new();
1067	    let mut leading_flags = String::new();
1068	    // Find the first takes_values option.
1069	    loop {
1070	        match short.next_flag() {
1071	            Some(Ok(opt)) => {
1072	                leading_flags.push(opt);
1073	                let opt = cmd.get_arguments().find(|a| is_short_match(a, opt));
1074	                if let Some(opt) = opt {
1075	                    matched_opts.push(opt);
1076	                }
1077	                if opt
1078	                    .map(|o| o.get_num_args().expect("built").takes_values())
1079	                    .unwrap_or(false)
1080	                {
1081	                    takes_value_opt = opt;
1082	                    break;
1083	                }
1084	            }
1085	            Some(Err(_)) | None => {
1086	                takes_value_opt = None;
1087	                break;
1088	            }
1089	        }
1090	    }
1091	
1092	    (leading_flags, matched_opts, takes_value_opt, short)
1093	}
