1095	/// Whether the argument can be addressed by the long flag `flag`,
1096	/// including visible and hidden aliases.
1097	fn is_long_match(arg: &clap::Arg, flag: &str) -> bool {
1098	    arg.get_long() == Some(flag)
1099	        || arg
1100	            .get_all_aliases()
1101	            .is_some_and(|aliases| aliases.contains(&flag))
1102	}
