1104	/// Whether the argument can be addressed by the short flag `flag`,
1105	/// including visible and hidden aliases.
1106	fn is_short_match(arg: &clap::Arg, flag: char) -> bool {
1107	    arg.get_short() == Some(flag)
1108	        || arg
1109	            .get_all_short_aliases()
1110	            .is_some_and(|aliases| aliases.contains(&flag))
1111	}
