1113	/// Remove argument candidates that are unavailable given the arguments
1114	/// already present on the command line.
1115	///
1116	/// Two rules apply:
1117	/// - Non-multiple argument groups: once any member of such a group is on the
1118	///   command line, every member of that group (including the selected one and
1119	///   all of its aliases) is removed, mirroring the parser's one-of constraint.
1120	/// - Explicit conflicts: a candidate that conflicts with an already-used
1121	///   argument is removed; conflicts only need to be declared on one side.
1122	///
1123	/// Anything that is not an argument candidate (positional values,
1124	/// subcommands, custom candidates) is left untouched.
1125	fn filter_unavailable_args(
1126	    completions: &mut Vec<CompletionCandidate>,
1127	    cmd: &clap::Command,
1128	    used_args: &[clap::Id],
1129	) {
1130	    if used_args.is_empty() {
1131	        return;
1132	    }
1133	
1134	    // Members of non-multiple groups that already have a member present.
1135	    let mut excluded_by_group = std::collections::HashSet::<clap::Id>::new();
1136	    for group in cmd.get_groups().filter(|group| !group.is_multiple_set()) {
1137	        let members: Vec<&clap::Id> = group.get_args().collect();
1138	        if members
1139	            .iter()
1140	            .any(|id| used_args.iter().any(|used| used == *id))
1141	        {
1142	            excluded_by_group.extend(members.into_iter().cloned());
1143	        }
1144	    }
1145	
1146	    completions.retain(|candidate| {
1147	        let Some(arg) = candidate
1148	            .get_id()
1149	            .and_then(|id| id.strip_prefix("arg::"))
1150	            .and_then(|id| cmd.get_arguments().find(|a| a.get_id() == id))
1151	        else {
1152	            return true;
1153	        };
1154	        if excluded_by_group.contains(arg.get_id()) {
1155	            return false;
1156	        }
1157	        !used_args.iter().any(|used_id| {
1158	            cmd.get_arguments()
1159	                .find(|a| a.get_id() == used_id)
1160	                .is_some_and(|used| args_conflict(cmd, arg, used))
1161	        })
1162	    });
1163	}
