1165	/// Record an argument seen on the command line, keeping the first occurrence
1166	/// only so that repeating a flag neither alters filtering nor restores
1167	/// candidates already excluded.
1168	fn record_used_arg(used_args: &mut Vec<clap::Id>, id: &clap::Id) {
1169	    if !used_args.iter().any(|used| used == id) {
1170	        used_args.push(id.clone());
1171	    }
1172	}
