1174	/// De-duplicate flag candidates.
1175	///
1176	/// With an empty word every long spelling of an argument (its long name and
1177	/// visible aliases) is offered, while short spellings are still collapsed to
1178	/// the canonical short and dropped for arguments that also have a long form.
1179	/// Once a prefix is typed at most one spelling of an argument can match, so
1180	/// candidates are de-duplicated by argument id as before.
1181	fn dedup_argument_candidates(completions: &mut Vec<CompletionCandidate>, empty_word: bool) {
1182	    if empty_word {
1183	        let long_ids: std::collections::HashSet<String> = completions
1184	            .iter()
1185	            .filter(|candidate| {
1186	                candidate.get_id().is_some() && candidate.get_value().starts_with("--")
1187	            })
1188	            .filter_map(|candidate| candidate.get_id().cloned())
1189	            .collect();
1190	        let mut seen_short_ids = std::collections::HashSet::new();
1191	        completions.retain(|candidate| {
1192	            let Some(id) = candidate.get_id() else {
1193	                return true;
1194	            };
1195	            if candidate.get_value().starts_with("--") {
1196	                // Keep the long name and every visible alias.
1197	                true
1198	            } else if long_ids.contains(id) {
1199	                // Prefer the long forms over the short ones.
1200	                false
1201	            } else {
1202	                seen_short_ids.insert(id.clone())
1203	            }
1204	        });
1205	    } else {
1206	        let mut seen_ids = std::collections::HashSet::new();
1207	        completions.retain(|candidate| {
1208	            if let Some(id) = candidate.get_id().cloned() {
1209	                seen_ids.insert(id)
1210	            } else {
1211	                true
1212	            }
1213	        });
1214	    }
1215	}
1216	
1217	/// Whether `first` and `second` conflict, no matter which one declares it.
1218	fn args_conflict(cmd: &clap::Command, first: &clap::Arg, second: &clap::Arg) -> bool {
1219	    cmd.get_arg_conflicts_with(first)
1220	        .iter()
1221	        .any(|c| c.get_id() == second.get_id())
1222	        || cmd
1223	            .get_arg_conflicts_with(second)
1224	            .iter()
1225	            .any(|c| c.get_id() == first.get_id())
1226	}
1227	
1228	/// The positional the parser would fill at `pos_index`.
1229	///
1230	/// A `last(true)` positional only exists after `--`; before the terminator
1231	/// the parser rejects values for it, so it must not be completed.
1232	fn find_positional(cmd: &clap::Command, pos_index: usize, is_escaped: bool) -> Option<&clap::Arg> {
1233	    cmd.get_positionals()
1234	        .find(|p| p.get_index() == Some(pos_index) && (is_escaped || !p.is_last_set()))
1235	}
1236	
1237	/// Parse the positional arguments. Return the new state and the new positional index.
1238	fn parse_positional<'a>(
1239	    cmd: &clap::Command,
1240	    pos_index: usize,
1241	    is_escaped: bool,
1242	    state: ParseState<'a>,
1243	) -> (ParseState<'a>, usize) {
1244	    let pos_arg = cmd
1245	        .get_positionals()
1246	        .find(|p| p.get_index() == Some(pos_index));
1247	    let num_args = pos_arg
1248	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
1249	        .unwrap_or(1);
1250	
1251	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
1252	        if num_args > 1 {
1253	            (ParseState::Pos((pos_index, 1)), pos_index)
1254	        } else {
1255	            if is_escaped {
1256	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
1257	            } else {
1258	                (ParseState::ValueDone, pos_index + 1)
1259	            }
1260	        }
1261	    };
1262	    match state {
1263	        ParseState::ValueDone => {
1264	            update_state_with_new_positional(pos_index)
1265	        },
1266	        ParseState::Pos((prev_pos_index, num_arg)) => {
1267	            if prev_pos_index == pos_index {
1268	                if num_arg + 1 < num_args {
1269	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
1270	                } else {
1271	                    if is_escaped {
1272	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
1273	                    } else {
1274	                        (ParseState::ValueDone, pos_index + 1)
1275	                    }
1276	                }
1277	            } else {
1278	                update_state_with_new_positional(pos_index)
1279	            }
1280	        }
1281	        ParseState::Opt(..) => unreachable!(
1282	            "This branch won't be hit,
1283	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
1284	        ),
1285	    }
1286	}
1287	
1288	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
1289	    cmd.get_positionals()
1290	        .find(|a| a.get_index() == Some(pos_index))
1291	        .map(|p| p.is_allow_hyphen_values_set())
1292	        .unwrap_or(false)
1293	}
1294	
1295	/// How many of an option's values an attached `=value` (or `-ovalue`) accounts
1296	/// for, honoring the value delimiter.
1297	fn attached_value_count(opt: &clap::Arg, value: &OsStr) -> usize {
1298	    match (opt.get_value_delimiter(), value.to_str()) {
1299	        (Some(delimiter), Some(value)) => value.split(delimiter).count(),
1300	        _ => 1,
1301	    }
1302	}
1303	
1304	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
1305	    let val = arg.to_value_os();
1306	    if val.starts_with("-") {
1307	        if let ParseState::Opt(state) = state {
1308	            return state.opt.is_allow_hyphen_values_set();
1309	        }
1310	    }
1311	
1312	    false
1313	}
1314	
1315	/// Whether `arg` is the standalone value terminator of a pending option.
1316	///
1317	/// Like the parser, an attached value (`--opt=;`) is not a terminator: the
1318	/// word must consist of the terminator alone.
1319	fn is_value_terminator(opt: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
1320	    opt.get_value_terminator()
1321	        .is_some_and(|term| arg.to_value_os() == OsStr::new(term.as_str()))
1322	}
1323	
1324	/// Whether the parser would route this word through flag/escape parsing before
1325	/// a pending option gets to consume it as a value.
1326	fn is_flag_like(arg: &clap_lex::ParsedArg<'_>) -> bool {
1327	    arg.is_escape() || arg.to_long().is_some() || arg.to_short().is_some()
1328	}
1329	
1330	/// Whether a word can terminate a still-open multi-value option and start a
1331	/// new argument instead, the way the parser would read it.
1332	///
1333	/// While an option still owes values, the parser greedily consumes every plain
1334	/// word as one of its values; only flag-like words can switch to another
1335	/// argument. An option that accepts hyphen values consumes those too.
1336	fn can_switch_to_other_arg(pending: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
1337	    if arg.is_escape() {
1338	        // `--` cancels every pending option unless its values may start with `--`.
1339	        return !pending.is_allow_hyphen_values_set();
1340	    }
1341	    if !arg.to_value_os().starts_with("-") {
1342	        // A plain word is always another value of the pending option.
1343	        return false;
1344	    }
1345	    if pending.is_allow_hyphen_values_set() {
1346	        return false;
1347	    }
1348	    // `-` is a stdio/value, not a flag.
1349	    if arg.is_stdio() {
1350	        return false;
1351	    }
1352	    // Both long and short flag styles can start a new argument; unknown flags
1353	    // still switch (and error during parsing) rather than become option values.
1354	    arg.to_long().is_some() || arg.to_short().is_some()
1355	}
