10	/// - `--output` takes one of `file`/`stream`
11	/// - the `run` subcommand (visible alias `r`) declares its own required,
12	///   non-multiple group whose members are the value-free `--text`/`--binary`
13	///   flags (visible aliases `--txt`/`--bin`) and accepts the positional
14	///   values `job`/`log`
15	fn mutex_group_tool() -> Command {
16	    Command::new("tool")
17	        .disable_help_flag(true)
18	        .disable_version_flag(true)
19	        .disable_help_subcommand(true)
20	        .arg(
21	            clap::Arg::new("json")
22	                .long("json")
23	                .visible_alias("js")
24	                .action(clap::ArgAction::SetTrue),
25	        )
26	        .arg(
27	            clap::Arg::new("yaml")
28	                .long("yaml")
29	                .visible_alias("yml")
30	                .action(clap::ArgAction::SetTrue),
31	        )
32	        .group(
