let mut current_cmd = &*cmd;
let mut pos_index = 1;
let mut is_escaped = false;
let mut next_state = ParseState::ValueDone;
let mut used_args = Vec::<clap::Id>::new();
// Whether an exclusive argument was committed at the current scope. Like
// the parser's exclusive constraint, no later word may name anything else
// (another option, a value, or a subcommand): every later word completes
// with an empty set. The latch resets on descending into a subcommand,
// whose scope starts with no consumed arguments.
let mut exclusive = false;
// Once a committed word selected an external subcommand, every remaining
// word belongs to that external program and is never completed here.
let mut in_external = false;
while let Some(arg) = raw_args.next(&mut cursor) {
    let current_state = next_state;
    next_state = ParseState::ValueDone;
    debug!(
        "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
        arg.to_value_os(),
    );
    if let ParseState::Opt(state) = &current_state {
        // A value terminator ends a multi-value option regardless of the
        // word's shape: unlike a flag-like word, it never starts a new
        // argument, and unlike any other word, it is never one of the
        // option's values. A flag-shaped terminator only wins over flag
        // parsing when the option accepts hyphen values, matching the
        // parser's precedence.
        let opt = state.opt;
        if is_value_terminator(opt, &arg)
            && (opt.is_allow_hyphen_values_set() || !is_flag_like(&arg))
        {
            if cursor == target_cursor {
                // The cursor sits on the terminator itself. Complete as if
                // it had already been submitted and an empty word followed,
                // so ordinary completion resumes and the terminator is not
                // offered as a candidate.
                raw_args.insert(&target_cursor, [OsString::new()]);
                let mut word_cursor = target_cursor;
                let word = raw_args
                    .next(&mut word_cursor)
                    .expect("an empty word was just inserted");
                return complete_arg(
                    &word,
                    current_cmd,
                    current_dir,
                    pos_index,
                    is_escaped,
                    ParseState::ValueDone,
                    &used_args,
                );
            }
            next_state = ParseState::ValueDone;
            continue;
        }
    }
    if in_external {
        // A committed word already selected an external subcommand; this
        // word (and every later one) is an argument of that external
        // program. Its command line is unknown, so rather than falling
        // back to the current command's subcommands, options, or
        // positionals, completion succeeds with an empty set.
        if cursor == target_cursor {
            return Ok(Vec::new());
        }
        continue;
    }

    if cursor == target_cursor {
        // While the exclusive argument is still waiting for its own value,
        // that value is the one thing allowed to complete; any other word
        // after a committed exclusive argument is blocked below.
        let completing_exclusive_value =
            matches!(&current_state, ParseState::Opt(state) if state.opt.is_exclusive_set());
        if exclusive && !completing_exclusive_value {
            // The cursor names a word after a committed exclusive
            // argument. The parser rejects anything that follows it, so
            // complete successfully with an empty set instead of offering
            // options, values, or subcommands that can never be accepted.
            return Ok(Vec::new());
        }
        return complete_arg(
            &arg,
            current_cmd,
            current_dir,
            pos_index,
            is_escaped,
            current_state,
            &used_args,
        );
    }

    if exclusive
        && !matches!(&current_state, ParseState::Opt(state) if state.opt.is_exclusive_set())
    {
        // A committed exclusive argument owns the rest of the scope: no
        // later word may descend into a subcommand, start another option,
        // or fill a positional. Swallowing the word (rather than parsing
        // it) keeps the latch set for every word that follows.
        continue;
    }

    if !is_escaped && !matches!(current_state, ParseState::Opt(..) | ParseState::Pos(..)) {
        if let Ok(value) = arg.to_value() {
            if let Some(next_cmd) = current_cmd.find_subcommand(value) {
                current_cmd = next_cmd;
                pos_index = 1;
                used_args.clear();
                // The subcommand's scope starts with no consumed
                // arguments, so an exclusive choice at the parent scope
                // does not carry into it.
                exclusive = false;
                continue;
            }
            // An unknown plain word, with no positional slot left to
            // fill, selects an external subcommand: the parser routes
            // everything after it to that external program. Flag-like
            // words and the escape are still parsed as flags, matching
            // that precedence, and an empty word is a cursor placeholder
            // rather than a program name.
            if current_cmd.is_allow_external_subcommands_set()
                && !arg.is_empty()
                && !arg.is_escape()
                && arg.to_long().is_none()
                && arg.to_short().is_none()
                && find_positional(current_cmd, pos_index, false).is_none()
            {
                in_external = true;
                continue;
            }

